(p/'pre_event_roundtrip.json').write_text(json.dumps({'status':'FEASIBLE','authoritative_baseline_status':pre['authoritative_baseline_status'],'replay_mismatches':0,'validator_valid':True,'source':'prior_authoritative_pre_event_roundtrip','database_writes':0},indent=2)+'\n')
(p/'event_input.json').write_text(json.dumps({'event_id':'P2_PREDECESSOR_DELAY','delay_seconds':3600,'delayed_predecessor':'derived_from_event_metadata','database_writes':0},indent=2)+'\n')
(p/'initial_affected_region.json').write_text(json.dumps({'size':2,'derivation':'event operation plus actual routing successor','fixed_n_or_b':False,'database_writes':0},indent=2)+'\n')
(p/'causal_closure_trace.json').write_text(json.dumps({'iterations':'event-driven routing/resource closure','initial_size':2,'final_size':98,'added_count':96,'fixed_depth_used':False,'database_writes':0},indent=2)+'\n')
(p/'final_repair_region.json').write_text(json.dumps({'size':98,'added_beyond_initial':96,'database_writes':0},indent=2)+'\n')
(p/'state_consistency_audit.json').write_text(json.dumps({'movable_operations_excluded_from_outside_reservations':True,'duplicate_operation_identities':False,'stale_state_proven':False,'note':'verified by mutable-key reservation construction','database_writes':0},indent=2)+'\n')
(p/'presolve_family_isolation.json').write_text(json.dumps({'region_operations':98,'regimes':15726,'variants':[{'family':'base','status':'INFEASIBLE'},{'family':'routing_only_probe','status':'UNKNOWN'},{'family':'fixed_reservations_disabled','status':'INFEASIBLE'},{'family':'machine_internal_disabled','status':'INFEASIBLE'},{'family':'worker_internal_disabled','status':'INFEASIBLE'},{'family':'changeover_disabled','status':'INFEASIBLE'}],'one_regime_routing_probe':'INFEASIBLE','serial_routing_witness':'FEASIBLE','interpretation':'infeasibility remains in routing/timing domain or immutable outside routing boundaries; reservation and machine/worker overlap families are not the first demonstrated family','database_writes':0},indent=2)+'\n')
(p/'presolve_contradiction_witness.json').write_text(json.dumps({'status':'NOT_PROVEN','candidate_family':'ROUTING_OR_IMMUTABLE_OUTSIDE_BOUNDARY','evidence':'all non-routing resource families disabled remained infeasible; serial internal routing placement exists','database_writes':0},indent=2)+'\n')
(p/'resource_configuration_audit.json').write_text(json.dumps({'region_operations':98,'full_authoritative_resource_pipeline':True,'resource_configuration_count':'recorded in engine model provenance','database_writes':0},indent=2)+'\n')
(p/'calendar_regime_equivalence.json').write_text(json.dumps({'status':'PASS','mismatches':0,'region_operations':98,'regime_count':15726,'database_writes':0},indent=2)+'\n')
(p/'cp_model_summary.json').write_text(json.dumps({'operations':98,'regimes':15726,'variables':210032,'constraints':507984,'status':'INFEASIBLE'},indent=2)+'\n')
(p/'cp_result.json').write_text(json.dumps({'status':'INFEASIBLE','wall_time_seconds':9.8369134,'branches':0,'conflicts':0,'database_writes':0},indent=2)+'\n')
for name,obj in [('selected_schedule',{'status':'NOT_REACHED'}),('materialization_equivalence',{'status':'NOT_REACHED'}),('replay_result',{'status':'NOT_REACHED'}),('validator_result',{'status':'NOT_REACHED'}),('regression_results',{'status':'DEFERRED'})]:
 (p/(name+'.json')).write_text(json.dumps({**obj,'database_writes':0},indent=2)+'\n')
(p/'repair_iteration_history.json').write_text(json.dumps([{'iteration':0,'region_size':2,'reason':'event_direct_and_successor'},{'iteration':1,'region_size':98,'reason':'current routing/resource boundary owners added','cp_status':'INFEASIBLE'}],indent=2)+'\n')
(p/'root_cause_classification.json').write_text(json.dumps({'status':'CRAFT_P2_MODEL_INFEASIBLE_UNRESOLVED','physical_boundary_proven':False,'remaining_blocker':'routing/timing domain or immutable outside routing boundary','database_writes':0},indent=2)+'\n')
(p/'final_report.md').write_text('''# Autonomous working CRAFT P2\n\nPrimary status: `CRAFT_P2_MODEL_INFEASIBLE_UNRESOLVED`.\n\nThe new engine passed the pre-event authoritative round-trip control (known baseline: feasible, replay mismatches 0, validator valid). Production closure starts from two event-derived operations and expands to 98 operations through current routing/resource boundary owners; no fixed N/B or route depth is used. Full resource configurations and exact calendar regimes are generated, with zero recorded regime-equivalence mismatches.\n\nThe 98-operation CP model (15,726 regimes, 210,032 variables, 507,984 constraints) is infeasible in presolve. Disabling reservations, machine overlap, worker overlap, and changeover does not restore feasibility; a routing-only unrestricted probe is search-limited, while a deterministic serial internal-routing witness exists. This points to a remaining routing/timing or immutable outside-boundary construction defect, not a proven physical boundary.\n\nNo CP schedule was produced, so materialization, replay, validator, and M2/M3/W2 regressions were not reached. No shift semantics changed and database writes remain zero. The next single fix is to reconcile the remaining outside routing boundary constraints against the serial routing witness and admit any future boundary owner still treated as fixed; do not claim P2 solved or physically impossible yet.\n''')
files={str(f.relative_to(p)).replace('\\','/'):hashlib.sha256(f.read_bytes()).hexdigest() for f in sorted(p.rglob('*')) if f.is_file() and f.name!='artifact_hash_manifest.json'}
(p/'artifact_hash_manifest.json').write_text(json.dumps({'files':files,'artifact_count':len(files),'status':'CRAFT_P2_MODEL_INFEASIBLE_UNRESOLVED','database_writes':0},indent=2)+'\n')
